('78', 'widget_text', 'a:4:{s:12:\"_multiwidget\";i:1;i:1;a:3:{s:5:\"title\";s:9:\"LetsDrive\";s:4:\"text\";s:396:\"<p style=\"color:#9ca3af;font-size:14px;line-height:1.7\">Premium 4WD and ute accessories for the Australian outback and beyond. Aussie-owned. Built tough.</p><p style=\"margin-top:16px\"><a href=\"/auto/shop/\" style=\"background:#E8502A;color:#fff;padding:10px 20px;border-radius:4px;text-decoration:none;font-weight:700;font-size:13px;letter-spacing:1px;text-transform:uppercase\">Shop Now →</a></p>\";s:6:\"filter\";b:0;}i:2;a:3:{s:5:\"title\";s:11:\"Quick Links\";s:4:\"text\";s:1021:\"<ul style=\"padding:0;margin:0\">\n<li style=\"margin-bottom:8px\"><a href=\"/auto/shop/\" style=\"color:#9ca3af;text-decoration:none;font-size:14px\">🛒 Shop All Products</a></li>\n<li style=\"margin-bottom:8px\"><a href=\"/auto/about/\" style=\"color:#9ca3af;text-decoration:none;font-size:14px\">ℹ️ About Us</a></li>\n<li style=\"margin-bottom:8px\"><a href=\"/auto/faq/\" style=\"color:#9ca3af;text-decoration:none;font-size:14px\">❓ FAQ</a></li>\n<li style=\"margin-bottom:8px\"><a href=\"/auto/shipping-information/\" style=\"color:#9ca3af;text-decoration:none;font-size:14px\">🚚 Shipping Info</a></li>\n<li style=\"margin-bottom:8px\"><a href=\"/auto/refund-and-returns-policy/\" style=\"color:#9ca3af;text-decoration:none;font-size:14px\">↩️ Returns Policy</a></li>\n<li style=\"margin-bottom:8px\"><a href=\"/auto/contact-us/\" style=\"color:#9ca3af;text-decoration:none;font-size:14px\">📞 Contact Us</a></li>\n<li><a href=\"/auto/privacy-policy/\" style=\"color:#9ca3af;text-decoration:none;font-size:14px\">🔒 Privacy Policy</a></li>\n</ul>\";s:6:\"filter\";b:0;}i:3;a:3:{s:5:\"title\";s:21:\"Contact &amp; Support\";s:4:\"text\";s:1117:\"<ul style=\"padding:0;margin:0;color:#9ca3af;font-size:14px\">\n<li style=\"margin-bottom:10px\">📧 <a href=\"mailto:hello@letsdrive.au\" style=\"color:#F5A623;text-decoration:none\">hello@letsdrive.au</a></li>\n<li style=\"margin-bottom:10px\">🕐