('1', '1', '2026-04-18 21:33:14', '2026-04-18 11:33:14', '<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->', 'Hello world!', '', 'publish', 'open', 'open', '', 'hello-world', '', '', '2026-04-18 21:33:14', '2026-04-18 11:33:14', '', '0', 'https://letsdrive.au/?p=1', '0', 'post', '', '1'),
('3', '1', '2026-04-18 21:33:14', '2026-04-18 11:33:14', '<!-- wp:html -->\n<style>\n.ru-legal { max-width:800px; margin:0 auto; padding:60px 40px; font-family:\"Barlow\",sans-serif; }\n.ru-legal h1 { font-family:\"Oswald\",sans-serif; font-size:clamp(26px,4vw,38px); font-weight:700; color:#1A1A2E; margin:0 0 8px; text-transform:uppercase; letter-spacing:1px; }\n.ru-legal-date { font-size:13px; color:#9CA3AF; margin:0 0 40px; }\n.ru-legal h2 { font-family:\"Oswald\",sans-serif; font-size:18px; font-weight:600; color:#1A1A2E; margin:32px 0 12px; border-left:3px solid #E8502A; padding-left:12px; text-transform:uppercase; }\n.ru-legal p, .ru-legal li { font-size:14px; color:#4B5563; line-height:1.9; margin:0 0 12px; }\n.ru-legal ul { padding-left:20px; }\n.ru-legal a { color:#E8502A; }\n@media(max-width:600px){ .ru-legal { padding:40px 20px; } }\n</style>\n<div class=\"ru-legal\">\n  <h1>Privacy Policy</h1>\n  <p class=\"ru-legal-date\">Last updated: April 2026</p>\n  <p>LetsDrive (\"<strong>we</strong>\", \"<strong>us</strong>\", \"<strong>our</strong>\") is committed to protecting your privacy in accordance with the Australian Privacy Act 1988 (Cth) and the Australian Privacy Principles (APPs).</p>\n  <h2>1. Information We Collect</h2>\n  <ul>\n    <li>Order details: name, email, phone, delivery address, payment details</li>\n    <li>Account or newsletter registration data</li>\n    <li>Enquiries submitted via contact form or email</li>\n    <li>Browsing data: IP address, browser type, pages visited (via cookies)</li>\n  </ul>\n  <h2>2. How We Use Your Information</h2>\n  <ul>\n    <li>Process and fulfil your orders</li>\n    <li>Send order confirmations, tracking, and tax invoices</li>\n    <li>Respond to fitment and support enquiries</li>\n    <li>Send marketing emails (only with your consent — unsubscribe any time)</li>\n    <li>Improve our website and product range</li>\n    <li>Comply with legal obligations</li>\n  </ul>\n  <h2>3. Payment Security</h2>\n  <p>We never store your credit card details. All payments are processed by Stripe (PCI DSS Level 1) or PayPal. Your card data is encrypted and inaccessible to us.</p>\n  <h2>4. Sharing Your Information</h2>\n  <ul>\n    <li><strong>Shipping carriers</strong> (Australia Post, TNT, Toll) — to deliver orders</li>\n    <li><strong>Stripe / PayPal</strong> — secure payment processing</li>\n    <li><strong>Mailchimp</strong> — email marketing (subscribers only)</li>\n    <li><strong>Google Analytics</strong> — anonymous traffic analysis</li>\n  </ul>\n  <h2>5. Cookies</h2>\n  <p>Cookies are used to maintain your cart, session, and preferences. You may disable cookies in browser settings though some features may be affected.</p>\n  <h2>6. Your Rights</h2>\n  <p>You have the right to access, correct, or request deletion of your personal data. Contact us at <a href=\"mailto:hello@letsdrive.au\">hello@letsdrive.au</a>.</p>\n  <h2>7. Data Retention</h2>\n  <p>We retain financial records for 7 years as required by Australian law. Other personal data is retained only as long as necessary.</p>\n  <h2>8. Contact</h2>\n  <p><strong>LetsDrive</strong><br>Email: <a href=\"mailto:hello@letsdrive.au\">hello@letsdrive.au</a></p>\n</div>\n<!-- /wp:html -->', 'Privacy Policy', '', 'publish', 'closed', 'open', '', 'privacy-policy', '', '', '2026-04-19 18:34:03', '2026-04-19 08:34:03', '', '0', 'https://letsdrive.au/?page_id=3', '0', 'page', '', '0'),
