('30', '0', '2026-04-19 15:10:52', '2026-04-19 05:10:52', '<!-- wp:html -->\n<style>\n.ru-about { font-family:\"Barlow\",sans-serif; }\n.ru-about-hero {\n  background:linear-gradient(135deg, #0d0d1a 0%, #1A1A2E 60%, #16213E 100%);\n  padding:80px 40px;\n  text-align:center;\n  color:#fff;\n  border-bottom:3px solid #E8502A;\n}\n.ru-about-hero h1 {\n  font-family:\"Oswald\",sans-serif;\n  font-size:clamp(32px,5vw,56px);\n  font-weight:700;\n  margin:0 0 16px;\n  color:#fff;\n  text-transform:uppercase;\n  letter-spacing:1px;\n}\n.ru-about-hero h1 span { color:#E8502A; }\n.ru-about-hero p { font-size:18px; color:rgba(245,245,240,0.8); max-width:600px; margin:0 auto; line-height:1.7; }\n.ru-about-body { max-width:900px; margin:0 auto; padding:60px 40px; }\n.ru-about-story { display:grid; grid-template-columns:1fr 1fr; gap:48px; align-items:center; margin-bottom:60px; }\n.ru-about-story-text h2 { font-family:\"Oswald\",sans-serif; font-size:32px; font-weight:700; color:#1A1A2E; margin:0 0 16px; text-transform:uppercase; letter-spacing:0.5px; }\n.ru-about-story-text p { font-size:15px; color:#4B5563; line-height:1.8; margin:0 0 16px; }\n.ru-about-visual {\n  background:linear-gradient(135deg, #1A1A2E, #16213E);\n  border:2px solid rgba(232,80,42,0.3);\n  border-radius:8px;\n  padding:48px 32px;\n  text-align:center;\n  color:#fff;\n}\n.ru-about-visual-icon { font-size:80px; margin-bottom:16px; display:block; }\n.ru-about-visual h3 { font-family:\"Oswald\",sans-serif; font-size:24px; margin:0 0 8px; text-transform:uppercase; color:#F5A623; }\n.ru-about-visual p { font-size:14px; color:rgba(245,245,240,0.7); margin:0; }\n.ru-values { background:#F5F5F0; border-radius:8px; padding:48px; margin-bottom:60px; }\n.ru-values h2 { font-family:\"Oswald\",sans-serif; font-size:28px; font-weight:700; color:#1A1A2E; margin:0 0 32px; text-align:center; text-transform:uppercase; }\n.ru-values-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:24px; }\n.ru-value-card { text-align:center; padding:24px 16px; background:#fff; border-radius:8px; border-bottom:3px solid #E8502A; }\n.ru-value-icon { font-size:36px; display:block; margin-bottom:12px; }\n.ru-value-title { font-weight:700; color:#1A1A2E; font-size:15px; margin:0 0 8px; font-family:\"Oswald\",sans-serif; text-transform:uppercase; letter-spacing:0.5px; }\n.ru-value-desc { font-size:13px; color:#636e72; line-height:1.6; margin:0; }\n.ru-promise { background:linear-gradient(135deg, #E8502A, #c73f1f); border-radius:8px; padding:48px; text-align:center; color:#fff; margin-bottom:60px; }\n.ru-promise h2 { font-family:\"Oswald\",sans-serif; font-size:28px; margin:0 0 12px; text-transform:uppercase; }\n.ru-promise p { font-size:15px; opacity:0.9; max-width:560px; margin:0 auto 24px; line-height:1.7; }\n.ru-promise-btn { display:inline-block; background:#fff; color:#E8502A; padding:14px 32px; border-radius:4px; font-weight:700; text-decoration:none; font-size:15px; font-family:\"Barlow\",sans-serif; letter-spacing:1px; text-transform:uppercase; }\n@media(max-width:700px){\n  .ru-about-story { grid-template-columns:1fr; }\n  .ru-values-grid { grid-template-columns:1fr; }\n  .ru-about-body { padding:40px 24px; }\n}\n</style>\n<div class=\"ru-about\">\n  <div class=\"ru-about-hero\">\n    <h1>About <span>LetsDrive</span> Auto</h1>\n    <p>Built by 4WD enthusiasts for 4WD enthusiasts. We live for the tracks, the mud, and the open road — and we want your rig to as well.</p>\n  </div>\n  <div class=\"ru-about-body\">\n    <div class=\"ru-about-story\">\n      <div class=\"ru-about-story-text\">\n        <h2>Our Story</h2>\n        <p>LetsDrive was born from frustration. Two mates who spent every weekend on the tracks were sick of paying dealership prices for accessories they could source directly — better and cheaper.</p>\n        <p>We spent a year building supplier relationships, field-testing gear on real Aussie terrain, and putting together a range that actually delivers. No gimmicks. No overpriced badges. Just tough gear that works.</p>\n        <p>Today we ship Australia-wide to 4WD owners, tradies, and off-road enthusiasts who demand the best for their rigs — without getting ripped off.</p>\n      </div>\n      <div class=\"ru-about-visual\">\n        <span class=\"ru-about-visual-icon\">🚙</span>\n        <h3>Gear Built for Australia</h3>\n        <p>Tested on red dirt tracks, coastal salt air, and everything the outback throws at you.</p>\n      </div>\n    </div>\n    <div class=\"ru-values\">\n      <h2>What We Stand For</h2>\n      <div class=\"ru-values-grid\">\n        <div class=\"ru-value-card\">\n          <span class=\"ru-value-icon\">🏁</span>\n          <div class=\"ru-value-title\">Aussie-Tested</div>\n          <p class=\"ru-value-desc\">Every product is field-tested in real Australian conditions before it makes our shelves.</p>\n        </div>\n        <div class=\"ru-value-card\">\n          <span class=\"ru-value-icon\">💰</span>\n          <div class=\"ru-value-title\">Fair Pricing</div>\n          <p class=\"ru-value-desc\">Direct sourcing means we cut out the middleman and pass the savings straight to you.</p>\n        </div>\n        <div class=\"ru-value-card\">\n          <span class=\"ru-value-icon\">🚀</span>\n          <div class=\"ru-value-title\">Fast Dispatch</div>\n          <p class=\"ru-value-desc\">Orders placed before 2pm AEST ship same day. Track every parcel door to door.</p>\n        </div>\n        <div class=\"ru-value-card\">\n          <span class=\"ru-value-icon\">🔧</span>\n          <div class=\"ru-value-title\">Technical Know-How</div>\n          <p class=\"ru-value-desc\">Our team knows 4WDs. Ask us anything about fitment, compatibility, or install.</p>\n        </div>\n        <div class=\"ru-value-card\">\n          <span class=\"ru-value-icon\">🔒</span>\n          <div class=\"ru-value-title\">Secure Shopping</div>\n          <p class=\"ru-value-desc\">SSL-encrypted checkout, Stripe card payments, and 30-day hassle-free returns.</p>\n        </div>\n        <div class=\"ru-value-card\">\n          <span class=\"ru-value-icon\">🇦🇺</span>\n          <div class=\"ru-value-title\">Aussie Owned</div>\n          <p class=\"ru-value-desc\">100% Australian owned and operated. We ship nationwide — metro, regional, remote.</p>\n        </div>\n      </div>\n    </div>\n    <div class=\"ru-promise\">\n      <h2>Our Guarantee</h2>\n      <p>Not happy? We&apos;ll sort it — no questions asked. 30-day returns, responsive local support, and a team that actually picks up the phone.</p>\n      <a href=\"/auto/shop/\" class=\"ru-promise-btn\">Shop Now →</a>\n    </div>\n  </div>\n</div>\n<!-- /wp:html -->', 'About Us', '', 'inherit', 'closed', 'closed', '', '13-revision-v1', '', '', '2026-04-19 15:10:52', '2026-04-19 05:10:52', '', '13', 'https://letsdrive.au/?p=30', '0', 'revision', '', '0'),
('31', '0', '2026-04-19 15:12:06', '2026-04-19 05:12:06', '<!-- wp:html -->\n<style>\n.ru-faq { max-width:800px; margin:0 auto; padding:60px 40px; font-family:\"Barlow\",sans-serif; }\n.ru-faq-hero { text-align:center; margin-bottom:48px; }\n.ru-faq-hero h1 { font-family:\"Oswald\",sans-serif; font-size:clamp(28px,4vw,42px); font-weight:700; color:#1A1A2E; margin:0 0 12px; text-transform:uppercase; letter-spacing:1px; }\n.ru-faq-hero p { font-size:16px; color:#636e72; margin:0; }\n.ru-faq-section { margin-bottom:40px; }\n.ru-faq-section-title { font-family:\"Oswald\",sans-serif; font-size:18px; font-weight:600; color:#E8502A; border-bottom:2px solid #F5F5F0; padding-bottom:8px; margin:0 0 20px; text-transform:uppercase; letter-spacing:0.5px; }\n.ru-faq-item { background:#F5F5F0; border-radius:6px; margin-bottom:10px; overflow:hidden; border-left:3px solid #E8502A; }\n.ru-faq-q { padding:18px 20px; font-weight:600; color:#1A1A2E; font-size:15px; cursor:pointer; }\n.ru-faq-a { padding:0 20px 16px; font-size:14px; color:#4B5563; line-height:1.8; }\n.ru-faq-cta { background:linear-gradient(135deg,#1A1A2E,#16213E); border:2px solid rgba(232,80,42,0.3); border-radius:8px; padding:36px; text-align:center; margin-top:40px; }\n.ru-faq-cta h3 { font-family:\"Oswald\",sans-serif; color:#fff; font-size:22px; margin:0 0 8px; text-transform:uppercase; }\n.ru-faq-cta p { color:rgba(245,245,240,0.75); margin:0 0 20px; font-size:15px; }\n.ru-faq-cta a { background:#E8502A; color:#fff; padding:12px 28px; border-radius:4px; text-decoration:none; font-weight:700; font-size:14px; font-family:\"Barlow\",sans-serif; letter-spacing:1px; text-transform:uppercase; }\n@media(max-width:600px){ .ru-faq { padding:40px 20px; } }\n</style>\n<div class=\"ru-faq\">\n  <div class=\"ru-faq-hero\">\n    <h1>Frequently Asked Questions</h1>\n    <p>Everything you need to know about shopping with LetsDrive.</p>\n  </div>\n\n  <div class=\"ru-faq-section\">\n    <div class=\"ru-faq-section-title\">🚚 Shipping &amp; Delivery</div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">How long does delivery take?</div>\n      <div class=\"ru-faq-a\">Standard delivery takes 5–10 business days Australia-wide. Express options are available at checkout. Remote areas (NT, outback WA/SA/QLD) may take 10–14 business days. Bulky items like roof racks may require additional transit time.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">Is shipping free?</div>\n      <div class=\"ru-faq-a\">Yes — free standard shipping on all orders over $100. Orders under $100 attract a flat $9.95 shipping fee. Free shipping applies to all Australian addresses including rural and remote areas.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">Do I get a tracking number?</div>\n      <div class=\"ru-faq-a\">Every order ships with full tracking, emailed to you at dispatch. You can monitor your parcel from our warehouse to your door in real time.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">Do you ship internationally?</div>\n      <div class=\"ru-faq-a\">We currently ship within Australia only. New Zealand and Pacific island shipping is on our roadmap — subscribe to our newsletter to be the first to know.</div>\n    </div>\n  </div>\n\n  <div class=\"ru-faq-section\">\n    <div class=\"ru-faq-section-title\">↩️ Returns &amp; Refunds</div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">What is your returns policy?</div>\n      <div class=\"ru-faq-a\">30-day returns on all items. Products must be unused and in original packaging. Email hello@letsdrive.au with your order number to start a return. We will organise a return label for eligible items.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">My item arrived damaged — what do I do?</div>\n      <div class=\"ru-faq-a\">Contact us within 7 days of delivery with a photo of the damage. We will send a replacement or issue a full refund — whichever you prefer, no hassle.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">How long do refunds take to process?</div>\n      <div class=\"ru-faq-a\">Refunds are processed within 3–5 business days of receiving the returned item. Your bank may take a further 5–10 business days to show the funds.</div>\n    </div>\n  </div>\n\n  <div class=\"ru-faq-section\">\n    <div class=\"ru-faq-section-title\">💳 Payments &amp; Security</div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">What payment methods do you accept?</div>\n      <div class=\"ru-faq-a\">We accept Visa, Mastercard, and American Express via Stripe, plus PayPal. All payments are SSL-encrypted and processed securely. We never store card details.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">Do prices include GST?</div>\n      <div class=\"ru-faq-a\">Yes. All listed prices include 10% Australian GST. A full tax invoice is generated and emailed with every order.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">Is the checkout secure?</div>\n      <div class=\"ru-faq-a\">Absolutely. Our checkout uses 256-bit SSL encryption and all card payments are processed by Stripe — a PCI DSS Level 1 certified payment provider trusted by millions of businesses worldwide.</div>\n    </div>\n  </div>\n\n  <div class=\"ru-faq-section\">\n    <div class=\"ru-faq-section-title\">🔧 Products &amp; Fitment</div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">How do I know if a product fits my vehicle?</div>\n      <div class=\"ru-faq-a\">Each product listing includes vehicle compatibility information where applicable. If you are unsure, email us at hello@letsdrive.au with your make, model, and year and we will confirm fitment before you buy.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">Do I need an account to order?</div>\n      <div class=\"ru-faq-a\">No — guest checkout is available. An account gives you order tracking, saved addresses, and full order history. It is free and takes 30 seconds to create.</div>\n    </div>\n    <div class=\"ru-faq-item\">\n      <div class=\"ru-faq-q\">How do I contact support?</div>\n      <div class=\"ru-faq-a\">Email hello@letsdrive.au or use our <a href=\"/auto/contact-us/\" style=\"color:#E8502A;\">Contact page</a>. We are available Mon–Fri 9am–5pm AEST and reply within 24 hours.</div>\n    </div>\n  </div>\n\n  <div class=\"ru-faq-cta\">\n    <h3>Still need help?</h3>\n    <p>Our team of 4WD enthusiasts is ready to assist — get in touch any time.</p>\n    <a href=\"/auto/contact-us/\">Contact Us →</a>\n  </div>\n</div>\n<!-- /wp:html -->', 'FAQ', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-04-19 15:12:06', '2026-04-19 05:12:06', '', '15', 'https://letsdrive.au/?p=31', '0', 'revision', '', '0'),
('32', '0', '2026-04-19 15:13:46', '2026-04-19 05:13:46', '<!-- wp:html -->\n<style>\n.ru-ship { max-width:800px; margin:0 auto; padding:60px 40px; font-family:\"Barlow\",sans-serif; }\n.ru-ship h1 { font-family:\"Oswald\",sans-serif; font-size:clamp(28px,4vw,40px); font-weight:700; color:#1A1A2E; margin:0 0 8px; text-transform:uppercase; letter-spacing:1px; }\n.ru-ship-intro { font-size:16px; color:#636e72; margin:0 0 40px; line-height:1.7; }\n.ru-ship-card { background:#F5F5F0; border-radius:6px; padding:28px; margin-bottom:20px; border-left:4px solid #E8502A; }\n.ru-ship-card h3 { font-family:\"Oswald\",sans-serif; font-size:18px; font-weight:600; color:#1A1A2E; margin:0 0 12px; text-transform:uppercase; }\n.ru-ship-card p, .ru-ship-card li { font-size:14px; color:#4B5563; line-height:1.8; margin:0 0 8px; }\n.ru-ship-card ul { padding-left:20px; }\n.ru-ship-table { width:100%; border-collapse:collapse; margin:16px 0; }\n.ru-ship-table th { background:#1A1A2E; color:#F5A623; padding:12px 16px; text-align:left; font-size:14px; font-weight:700; font-family:\"Oswald\",sans-serif; text-transform:uppercase; letter-spacing:0.5px; }\n.ru-ship-table td { padding:12px 16px; font-size:14px; color:#4B5563; border-bottom:1px solid #e5e7eb; }\n.ru-ship-table tr:last-child td { border-bottom:none; }\n.ru-ship-highlight { background:linear-gradient(135deg,#E8502A,#c73f1f); border-radius:6px; padding:28px; text-align:center; color:#fff; margin-top:32px; }\n.ru-ship-highlight h3 { font-family:\"Oswald\",sans-serif; font-size:22px; margin:0 0 8px; text-transform:uppercase; }\n.ru-ship-highlight p { font-size:15px; opacity:0.9; margin:0; }\n@media(max-width:600px){ .ru-ship { padding:40px 20px; } }\n</style>\n<div class=\"ru-ship\">\n  <h1>Shipping Information</h1>\n  <p class=\"ru-ship-intro\">We ship all orders Australia-wide — metro, regional, and remote. Here is everything you need to know about how we get your gear delivered.</p>\n\n  <div class=\"ru-ship-card\">\n    <h3>🚚 Delivery Timeframes</h3>\n    <table class=\"ru-ship-table\">\n      <tr><th>Location</th><th>Standard</th><th>Express</th></tr>\n      <tr><td>Metro (Sydney, Melbourne, Brisbane, Perth, Adelaide)</td><td>3–7 business days</td><td>1–3 business days</td></tr>\n      <tr><td>Regional Centres</td><td>5–10 business days</td><td>2–5 business days</td></tr>\n      <tr><td>Rural &amp; Remote</td><td>10–14 business days</td><td>5–10 business days</td></tr>\n    </table>\n    <p>Orders placed before <strong>2pm AEST</strong> on business days are dispatched same day. Note: bulky items (roof racks, bull bars) may require 1–2 additional days for packing.</p>\n  </div>\n\n  <div class=\"ru-ship-card\">\n    <h3>💸 Shipping Rates</h3>\n    <table class=\"ru-ship-table\">\n      <tr><th>Order Value</th><th>Shipping Cost</th></tr>\n      <tr><td>Under $100</td><td>$9.95 flat rate</td></tr>\n      <tr><td>$100 and over</td><td><strong>FREE</strong></td></tr>\n    </table>\n  </div>\n\n  <div class=\"ru-ship-card\">\n    <h3>📦 How We Ship</h3>\n    <ul>\n      <li>All items are packed securely — heavy items use reinforced cartons and pallet wrap where required</li>\n      <li>Tracking numbers are emailed immediately upon dispatch</li>\n      <li>We use trusted carriers including Australia Post, TNT, and Toll for freight items</li>\n      <li>Signature on delivery is required for orders over $250 and all freight items</li>\n    </ul>\n  </div>\n\n  <div class=\"ru-ship-card\">\n    <h3>❓ Delayed or Lost Parcel?</h3>\n    <p>If your order has not arrived within the estimated window, contact us at <a href=\"mailto:hello@letsdrive.au\" style=\"color:#E8502A;\">hello@letsdrive.au</a> with your order number. We will investigate with the carrier immediately. All lost parcels are fully covered.</p>\n  </div>\n\n  <div class=\"ru-ship-highlight\">\n    <h3>Free Shipping on Orders $100+</h3>\n    <p>Australia-wide. No exclusions. Add more gear and we cover the freight.</p>\n  </div>\n</div>\n<!-- /wp:html -->', 'Shipping Information', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-04-19 15:13:46', '2026-04-19 05:13:46', '', '16', 'https://letsdrive.au/?p=32', '0', 'revision', '', '0'),
