('34', '0', '2026-04-19 15:22:42', '2026-04-19 05:22:42', '<!-- wp:html -->\n<style>\n.ru-contact { font-family:\"Barlow\",sans-serif; }\n.ru-contact-hero { background:linear-gradient(135deg,#0d0d1a,#1A1A2E); padding:60px 40px; text-align:center; color:#fff; border-bottom:3px solid #E8502A; }\n.ru-contact-hero h1 { font-family:\"Oswald\",sans-serif; font-size:clamp(28px,4vw,42px); font-weight:700; margin:0 0 12px; color:#fff; text-transform:uppercase; letter-spacing:1px; }\n.ru-contact-hero p { font-size:16px; color:rgba(245,245,240,0.8); max-width:500px; margin:0 auto; }\n.ru-contact-body { max-width:900px; margin:0 auto; padding:60px 40px; display:grid; grid-template-columns:1fr 1fr; gap:48px; }\n.ru-contact-info h2 { font-family:\"Oswald\",sans-serif; font-size:24px; font-weight:700; color:#1A1A2E; margin:0 0 20px; text-transform:uppercase; }\n.ru-contact-info-item { display:flex; gap:14px; align-items:flex-start; margin-bottom:24px; }\n.ru-contact-info-icon { width:44px; height:44px; background:#F5F5F0; border-radius:4px; border:1px solid rgba(232,80,42,0.2); display:flex; align-items:center; justify-content:center; font-size:20px; flex-shrink:0; }\n.ru-contact-info-text strong { display:block; color:#1A1A2E; font-size:14px; font-weight:700; margin-bottom:4px; }\n.ru-contact-info-text span { color:#636e72; font-size:14px; line-height:1.6; }\n.ru-contact-info-text a { color:#E8502A; text-decoration:none; }\n.ru-contact-form-wrap { background:#F5F5F0; border-radius:8px; padding:32px; border-top:3px solid #E8502A; }\n.ru-contact-form-wrap h2 { font-family:\"Oswald\",sans-serif; font-size:22px; font-weight:700; color:#1A1A2E; margin:0 0 20px; text-transform:uppercase; }\n.wpcf7-form input[type=text], .wpcf7-form input[type=email], .wpcf7-form textarea {\n  width:100%; padding:12px 16px; border:2px solid #e5e7eb; border-radius:4px; font-size:14px; font-family:\"Barlow\",sans-serif; box-sizing:border-box; margin-bottom:12px; background:#fff; color:#1A1A2E; outline:none; transition:border-color 0.2s;\n}\n.wpcf7-form input:focus, .wpcf7-form textarea:focus { border-color:#E8502A; }\n.wpcf7-form input[type=submit] { background:#E8502A; color:#fff; border:none; padding:14px 32px; border-radius:4px; font-weight:700; font-size:14px; font-family:\"Barlow\",sans-serif; cursor:pointer; width:100%; transition:background 0.2s; letter-spacing:1px; text-transform:uppercase; }\n.wpcf7-form input[type=submit]:hover { background:#c73f1f; }\n@media(max-width:700px){ .ru-contact-body { grid-template-columns:1fr; padding:40px 24px; } }\n</style>\n<div class=\"ru-contact\">\n  <div class=\"ru-contact-hero\">\n    <h1>Contact Us</h1>\n    <p>Got a fitment question or need help with your order? Our team knows 4WDs — reach out any time.</p>\n  </div>\n  <div class=\"ru-contact-body\">\n    <div class=\"ru-contact-info\">\n      <h2>Get in Touch</h2>\n      <div class=\"ru-contact-info-item\">\n        <div class=\"ru-contact-info-icon\">📧</div>\n        <div class=\"ru-contact-info-text\">\n          <strong>Email Us</strong>\n          <span><a href=\"mailto:hello@letsdrive.au\">hello@letsdrive.au</a><br>We reply within 24 hours</span>\n        </div>\n      </div>\n      <div class=\"ru-contact-info-item\">\n        <div class=\"ru-contact-info-icon\">🕐</div>\n        <div class=\"ru-contact-info-text\">\n          <strong>Business Hours</strong>\n          <span>Monday – Friday<br>9:00am – 5:00pm AEST</span>\n        </div>\n      </div>\n      <div class=\"ru-contact-info-item\">\n        <div class=\"ru-contact-info-icon\">🔧</div>\n        <div class=\"ru-contact-info-text\">\n          <strong>Fitment Enquiries</strong>\n          <span>Tell us your vehicle make, model, and year — we will confirm compatibility before you buy.</span>\n        </div>\n      </div>\n      <div class=\"ru-contact-info-item\">\n        <div class=\"ru-contact-info-icon\">↩️</div>\n        <div class=\"ru-contact-info-text\">\n          <strong>Returns</strong>\n          <span>See our <a href=\"/auto/refund-and-returns-policy/\">Returns Policy</a> — 30-day hassle-free returns.</span>\n        </div>\n      </div>\n    </div>\n    <div class=\"ru-contact-form-wrap\">\n      <h2>Send a Message</h2>\n      [contact-form-7 id=\"contact-form\"]\n    </div>\n  </div>\n</div>\n<!-- /wp:html -->', 'Contact Us', '', 'inherit', 'closed', 'closed', '', '14-revision-v1', '', '', '2026-04-19 15:22:42', '2026-04-19 05:22:42', '', '14', 'https://letsdrive.au/?p=34', '0', 'revision', '', '0'),
('36', '0', '2026-04-19 18:03:49', '2026-04-19 08:03:49', '@import url(\"https://fonts.googleapis.com/css2?family=Barlow:wght@300;400;600;700;800;900&family=Barlow+Condensed:wght@600;700;800&family=Oswald:wght@400;500;600;700&display=swap\");\n\n/* Global font overrides */\nbody, p, li, td, input, button, select, textarea {\n  font-family: \"Barlow\", sans-serif !important;\n}\nh1, h2, h3, h4, h5, h6,\n.woocommerce-loop-product__title,\n.product_title,\n.woocommerce h1, .woocommerce h2 {\n  font-family: \"Oswald\", sans-serif !important;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n/* Header dark background */\n#masthead, .ast-header-sticked, .site-header {\n  background: #1A1A2E !important;\n}\n.ast-site-identity a, .site-title a { color: #F5A623 !important; }\n.main-header-menu > li > a, .main-navigation a {\n  color: #F5F5F0 !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 600 !important;\n  letter-spacing: 0.5px;\n}\n.main-header-menu > li > a:hover { color: #E8502A !important; }\n\n/* WooCommerce product cards */\n.woocommerce ul.products li.product .button {\n  background: #E8502A !important;\n  color: #fff !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n  font-size: 13px !important;\n}\n.woocommerce ul.products li.product .button:hover {\n  background: #c73f1f !important;\n}\n.woocommerce ul.products li.product {\n  border-radius: 6px;\n  overflow: hidden;\n  box-shadow: 0 4px 16px rgba(26,26,46,0.08);\n  border: 1px solid #e5e7eb;\n  transition: transform 0.25s, box-shadow 0.25s;\n}\n.woocommerce ul.products li.product:hover {\n  transform: translateY(-4px);\n  box-shadow: 0 12px 32px rgba(232,80,42,0.12);\n  border-color: #E8502A;\n}\n/* Price */\n.woocommerce .price, .woocommerce-page .price {\n  color: #E8502A !important;\n  font-weight: 700 !important;\n  font-family: \"Barlow\", sans-serif !important;\n}\n/* Add to cart - single product */\n.woocommerce .single_add_to_cart_button {\n  background: #E8502A !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n  padding: 16px 40px !important;\n}\n.woocommerce .single_add_to_cart_button:hover { background: #c73f1f !important; }\n/* Cart/checkout */\n.woocommerce .checkout-button,\n.woocommerce a.button.alt,\n.woocommerce button.button.alt {\n  background: #E8502A !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n}\n/* Sale badge */\n.woocommerce span.onsale {\n  background: #E8502A !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n}\n/* Star ratings */\n.woocommerce .star-rating span::before,\n.woocommerce .star-rating::before { color: #F5A623; }\n/* Breadcrumbs */\n.woocommerce .woocommerce-breadcrumb a { color: #E8502A; }\n/* WooCommerce notices */\n.woocommerce-message { border-top-color: #E8502A !important; }\n/* Footer background */\n.ast-small-footer, footer.ast-small-footer { background: #1A1A2E !important; color: #9ca3af !important; }\n.ast-small-footer a { color: #F5A623 !important; }\n/* Mobile hamburger */\n@media (max-width: 768px) {\n  .ast-mobile-menu-trigger-fill { background: #E8502A !important; }\n  #masthead { border-bottom: 2px solid #E8502A !important; }\n}\n/* ── Homepage: remove container padding, hide page title ── */\n.home .entry-title,\n.home .ast-page-header,\n.home .page-header { display: none !important; }\n\n.home .ast-container,\n.home .entry-content { padding-left: 0 !important; padding-right: 0 !important; max-width: 100% !important; }\n\n.home .site-content .ast-container { padding: 0 !important; }\n.home article.page { padding: 0 !important; margin: 0 !important; }\n.home .entry-content .wp-block-group__inner-container { max-width: 100%; }\n\n/* Fix full-width page on Astra */\n.page-template-page-fullwidth .ast-container,\n.page-template-page-fullwidth .entry-content { max-width: 100% !important; padding: 0 !important; }\n\n/* Remove top/bottom spacing on homepage */\n.home #content.site-content { padding-top: 0 !important; }\n.home .ast-article-single { padding: 0 !important; margin: 0 !important; }\n\n/* ── Homepage full-width: override Astra CSS vars ── */\nbody.home {\n  --ast-normal-container-width: 100% !important;\n  --ast-container-default-xlg-padding: 0 !important;\n  --ast-container-default-lg-padding: 0 !important;\n  --ast-container-default-slg-padding: 0 !important;\n  --ast-container-default-md-padding: 0 !important;\n  --ast-container-default-sm-padding: 0 !important;\n  --ast-container-default-xs-padding: 0 !important;\n  --ast-container-default-xxs-padding: 0 !important;\n}\nbody.home .entry-header,\nbody.home h1.entry-title { display: none !important; }\nbody.home .ast-container { max-width: 100% !important; padding: 0 !important; }\nbody.home .entry-content { padding: 0 !important; max-width: 100% !important; }\nbody.home #content.site-content { padding-top: 0 !important; padding-bottom: 0 !important; }\nbody.home .ast-article-single { padding: 0 !important; margin: 0 !important; }\nbody.home #primary { padding: 0 !important; }\n\n/* ── Homepage: full-width, no title ── */\nbody.home h1.entry-title,\nbody.home .entry-header { display: none !important; }\nbody.home {\n  --ast-normal-container-width: 100%;\n  --ast-container-default-xlg-padding: 0px;\n  --ast-container-default-lg-padding: 0px;\n  --ast-container-default-slg-padding: 0px;\n  --ast-container-default-md-padding: 0px;\n  --ast-container-default-sm-padding: 0px;\n  --ast-container-default-xs-padding: 0px;\n  --ast-container-default-xxs-padding: 0px;\n}\nbody.home .ast-container { max-width: 100% !important; padding-left: 0 !important; padding-right: 0 !important; }\nbody.home #primary, body.home .entry-content { padding: 0 !important; max-width: 100% !important; }\nbody.home #content.site-content { padding-top: 0 !important; }\nbody.home .ast-article-single { padding: 0 !important; margin: 0 !important; }\n', 'Custom CSS', '', 'publish', 'closed', 'closed', '', 'astra', '', '', '2026-04-19 22:53:29', '2026-04-19 12:53:29', '', '0', 'https://letsdrive.au/custom-css/', '0', 'custom_css', '', '0'),
('37', '0', '2026-04-19 18:34:03', '2026-04-19 08:34:03', '<!-- wp:html -->\n<style>\n.ru-legal { max-width:800px; margin:0 auto; padding:60px 40px; font-family:\"Barlow\",sans-serif; }\n.ru-legal h1 { font-family:\"Oswald\",sans-serif; font-size:clamp(26px,4vw,38px); font-weight:700; color:#1A1A2E; margin:0 0 8px; text-transform:uppercase; letter-spacing:1px; }\n.ru-legal-date { font-size:13px; color:#9CA3AF; margin:0 0 40px; }\n.ru-legal h2 { font-family:\"Oswald\",sans-serif; font-size:18px; font-weight:600; color:#1A1A2E; margin:32px 0 12px; border-left:3px solid #E8502A; padding-left:12px; text-transform:uppercase; }\n.ru-legal p, .ru-legal li { font-size:14px; color:#4B5563; line-height:1.9; margin:0 0 12px; }\n.ru-legal ul { padding-left:20px; }\n.ru-legal a { color:#E8502A; }\n@media(max-width:600px){ .ru-legal { padding:40px 20px; } }\n</style>\n<div class=\"ru-legal\">\n  <h1>Privacy Policy</h1>\n  <p class=\"ru-legal-date\">Last updated: April 2026</p>\n  <p>LetsDrive (\"<strong>we</strong>\", \"<strong>us</strong>\", \"<strong>our</strong>\") is committed to protecting your privacy in accordance with the Australian Privacy Act 1988 (Cth) and the Australian Privacy Principles (APPs).</p>\n  <h2>1. Information We Collect</h2>\n  <ul>\n    <li>Order details: name, email, phone, delivery address, payment details</li>\n    <li>Account or newsletter registration data</li>\n    <li>Enquiries submitted via contact form or email</li>\n    <li>Browsing data: IP address, browser type, pages visited (via cookies)</li>\n  </ul>\n  <h2>2. How We Use Your Information</h2>\n  <ul>\n    <li>Process and fulfil your orders</li>\n    <li>Send order confirmations, tracking, and tax invoices</li>\n    <li>Respond to fitment and support enquiries</li>\n    <li>Send marketing emails (only with your consent — unsubscribe any time)</li>\n    <li>Improve our website and product range</li>\n    <li>Comply with legal obligations</li>\n  </ul>\n  <h2>3. Payment Security</h2>\n  <p>We never store your credit card details. All payments are processed by Stripe (PCI DSS Level 1) or PayPal. Your card data is encrypted and inaccessible to us.</p>\n  <h2>4. Sharing Your Information</h2>\n  <ul>\n    <li><strong>Shipping carriers</strong> (Australia Post, TNT, Toll) — to deliver orders</li>\n    <li><strong>Stripe / PayPal</strong> — secure payment processing</li>\n    <li><strong>Mailchimp</strong> — email marketing (subscribers only)</li>\n    <li><strong>Google Analytics</strong> — anonymous traffic analysis</li>\n  </ul>\n  <h2>5. Cookies</h2>\n  <p>Cookies are used to maintain your cart, session, and preferences. You may disable cookies in browser settings though some features may be affected.</p>\n  <h2>6. Your Rights</h2>\n  <p>You have the right to access, correct, or request deletion of your personal data. Contact us at <a href=\"mailto:hello@letsdrive.au\">hello@letsdrive.au</a>.</p>\n  <h2>7. Data Retention</h2>\n  <p>We retain financial records for 7 years as required by Australian law. Other personal data is retained only as long as necessary.</p>\n  <h2>8. Contact</h2>\n  <p><strong>LetsDrive</strong><br>Email: <a href=\"mailto:hello@letsdrive.au\">hello@letsdrive.au</a></p>\n</div>\n<!-- /wp:html -->', 'Privacy Policy', '', 'inherit', 'closed', 'closed', '', '3-revision-v1', '', '', '2026-04-19 18:34:03', '2026-04-19 08:34:03', '', '3', 'https://letsdrive.au/?p=37', '0', 'revision', '', '0'),
('38', '0', '2026-04-19 18:34:05', '2026-04-19 08:34:05', '<!-- wp:html -->\n<style>\n.ru-legal { max-width:800px; margin:0 auto; padding:60px 40px; font-family:\"Barlow\",sans-serif; }\n.ru-legal h1 { font-family:\"Oswald\",sans-serif; font-size:clamp(26px,4vw,38px); font-weight:700; color:#1A1A2E; margin:0 0 8px; text-transform:uppercase; letter-spacing:1px; }\n.ru-legal-date { font-size:13px; color:#9CA3AF; margin:0 0 40px; }\n.ru-legal h2 { font-family:\"Oswald\",sans-serif; font-size:18px; font-weight:600; color:#1A1A2E; margin:32px 0 12px; border-left:3px solid #E8502A; padding-left:12px; text-transform:uppercase; }\n.ru-legal p, .ru-legal li { font-size:14px; color:#4B5563; line-height:1.9; margin:0 0 12px; }\n.ru-legal ul { padding-left:20px; }\n.ru-legal a { color:#E8502A; }\n.ru-legal-highlight { background:#F5F5F0; border-radius:6px; padding:24px; margin:24px 0; border-left:4px solid #E8502A; }\n.ru-legal-highlight p { margin:0; font-weight:600; color:#1A1A2E; }\n@media(max-width:600px){ .ru-legal { padding:40px 20px; } }\n</style>\n<div class=\"ru-legal\">\n  <h1>Refund &amp; Returns Policy</h1>\n  <p class=\"ru-legal-date\">Last updated: April 2026</p>\n  <div class=\"ru-legal-highlight\">\n    <p>🔧 &nbsp;Not happy with your order? We will sort it — no questions asked.</p>\n  </div>\n  <h2>Returns Window</h2>\n  <p>Return most items within <strong>30 days of delivery</strong>. Items must be:</p>\n  <ul>\n    <li>Unused and in original condition</li>\n    <li>In original packaging with all accessories and hardware included</li>\n    <li>Accompanied by your order number</li>\n  </ul>\n  <h2>Non-Returnable Items</h2>\n  <ul>\n    <li>Items that have been installed, drilled, or modified</li>\n    <li>Custom-cut or made-to-order products</li>\n    <li>Electrical items once fitted (due to safety regulations)</li>\n    <li>Items returned more than 30 days after delivery</li>\n  </ul>\n  <h2>How to Start a Return</h2>\n  <p>Email <a href=\"mailto:hello@letsdrive.au\">hello@letsdrive.au</a> with your order number, the item(s) you wish to return, and reason. We will respond within 1 business day with a return label.</p>\n  <h2>Damaged or Incorrect Items</h2>\n  <p>Contact us within <strong>7 days of delivery</strong> with a photo of the damage or incorrect item. We will send a replacement or full refund — no return required.</p>\n  <h2>Refund Processing</h2>\n  <ul>\n    <li>Processed within <strong>3–5 business days</strong> of receiving the return</li>\n    <li>Refunded to your original payment method</li>\n    <li>Allow 5–10 business days to appear on your statement</li>\n    <li>Return shipping is at your cost unless the error was ours</li>\n  </ul>\n  <h2>Exchanges</h2>\n  <p>We do not process direct exchanges. Return the original item for a refund and place a new order for the correct product.</p>\n  <h2>Questions?</h2>\n  <p>Email <a href=\"mailto:hello@letsdrive.au\">hello@letsdrive.au</a> — Mon–Fri 9am–5pm AEST. We always reply within 24 hours.</p>\n</div>\n<!-- /wp:html -->', 'Refund and Returns Policy', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2026-04-19 18:34:05', '2026-04-19 08:34:05', '', '10', 'https://letsdrive.au/?p=38', '0', 'revision', '', '0'),
('39', '1', '2026-04-19 21:03:39', '2026-04-19 11:03:39', '<h3>Stop Losing Gear on the Job — Lock It Down with the LetsDrive Aluminium Ute Toolbox</h3><p>If you\'re sick of tools rattling around the tray or going missing on site, it\'s time to sort yourself out. This 1380mm aluminium ute toolbox is built tough for the bush and tough enough for the daily grind — whether you\'re on a dusty outback track or parked up at a suburban job site.</p><ul><li><strong>Aircraft-grade aluminium construction</strong> — lightweight but seriously strong, won\'t rust, won\'t buckle under heavy loads</li><li><strong>Dual-piston gas struts</strong> — lid stays open hands-free while you rummage through your gear, no more lid dropping on your knuckles</li><li><strong>Heavy-duty barrel lock with two keys</strong> — keep your tools secure from sticky fingers on and off site</li><li><strong>Universal fitment</strong> — suits most single cab, extra cab and dual cab utes including HiLux, Ranger, BT-50, Colorado and Navara</li><li><strong>Weather-sealed rubber gasket</strong> — keeps rain, dust and mud out of your tools, Aussie-tested in all conditions</li></ul><p>This isn\'t some flimsy import that\'ll cave in after three months. The LetsDrive toolbox ships fully assembled and ready to bolt straight onto your tray — no drilling, no stuffing around. With a deep 300mm internal depth, you\'ve got room for power tools, safety gear, tie-down straps and everything else you haul daily.</p><p>Gear up your ute the right way. We offer fast delivery across Australia — most metro orders arrive in 3–5 business days. Regional and rural delivery available nationwide.</p><p><strong>Don\'t wait until your tools get knocked off. Grab yours today before stock runs out.</strong></p>', 'Heavy Duty Ute Tray Toolbox 1380mm Aluminium Lock', '1380mm heavy-duty aluminium ute toolbox with dual gas struts and barrel lock — built tough for tradies across Australia. Fast nationwide delivery, universal tray fitment.', 'publish', 'open', 'closed', '', 'heavy-duty-ute-tray-toolbox-1380mm-aluminium-lock', '', '', '2026-04-19 21:20:29', '2026-04-19 11:20:29', '', '0', 'https://localhost/auto/product/heavy-duty-ute-tray-toolbox-1380mm-aluminium-lock/', '0', 'product', '', '0'),
('40', '1', '2026-04-19 21:03:40', '2026-04-19 11:03:40', '<h3>Flat Tyre in the Middle of Nowhere? Not on Our Watch.</h3><p>Every serious four-wheel driver knows the feeling — you\'re deep in the scrub, kilometres from the nearest servo, and you\'ve copped a soft tyre on a rough track. The LetsDrive 150PSI Portable Air Compressor is the piece of kit that gets you moving again without flagging down a stranger or waiting on roadside assist.</p><ul><li><strong>150PSI max pressure</strong> — powers through re-inflating 4WD, SUV and truck tyres fast, from flat to full in under 10 minutes</li><li><strong>Direct 12V cigarette lighter connection</strong> — no external power needed, just plug into your rig and go</li><li><strong>Built-in digital pressure gauge</strong> — accurate to 0.5PSI so you hit your target pressure every time, no guesswork</li><li><strong>Auto shut-off function</strong> — set your desired PSI and walk away, it cuts out automatically when it hits the mark</li><li><strong>Heavy-duty braided air hose 3 metres long</strong> — reaches all four tyres without moving the vehicle, Aussie-tested on corrugated dirt tracks</li></ul><p>Compact enough to live in your centre console, tough enough to handle the demands of off-road recovery. Comes with three nozzle adaptors — fits car tyres, bike tyres, air mattresses and sporting equipment. The carry bag keeps everything together so you\'re not hunting for bits when you need it most.</p><p>This is non-negotiable gear for anyone who takes 4WD parts and recovery seriously in Australia. Chuck it in the rig, forget it\'s there, and be grateful when you need it.</p><p><strong>Order today — fast delivery to metro and regional Australia. Don\'t head bush without one.</strong></p>', '12V Portable Air Compressor 4WD Tyre Inflator 150PSI', '150PSI 12V portable tyre inflator with auto shut-off and digital gauge — essential 4WD recovery gear for Australian tracks. Plug-and-go, fits all utes and 4WDs.', 'publish', 'open', 'closed', '', '12v-portable-air-compressor-4wd-tyre-inflator-150psi', '', '', '2026-04-19 21:20:24', '2026-04-19 11:20:24', '', '0', 'https://localhost/auto/product/12v-portable-air-compressor-4wd-tyre-inflator-150psi/', '0', 'product', '', '0'),
('41', '1', '2026-04-19 21:03:40', '2026-04-19 11:03:40', '<h3>Blind Spots on the Track Are Gone — Light Up the Night with the LetsDrive 22\" LED Light Bar</h3><p>Whether you\'re navigating a cattle station at midnight or pushing through the Kimberley at dusk, you need lighting that doesn\'t mess around. The LetsDrive 22-inch LED light bar throws a brutal combo of spot and flood beam that cuts through dust, fog, rain and darkness like it\'s nothing.</p><ul><li><strong>120W true output with 8,400 lumens</strong> — genuine brightness that actually matches the spec sheet, not inflated marketing numbers</li><li><strong>Spot and flood combo beam pattern</strong> — flood beam widens your peripheral vision on trails, spot beam reaches hundreds of metres ahead on open tracks</li><li><strong>IP67 waterproof and dustproof rating</strong> — sealed tight against creek crossings, river fords and outback dust storms, built tough for the bush</li><li><strong>Durable die-cast aluminium housing</strong> — dissipates heat fast, survives vibration on corrugated tracks without flickering or failing</li><li><strong>Universal mounting bracket included</strong> — bolt to bull bar, roof rack or bonnet — fits most 4WD and ute setups, wiring harness and switch included</li></ul><p>Each LED chip is rated at 50,000 hours of life. That\'s years of night drives before you even think about replacing a globe. The polycarbonate lens is scratch-resistant and treated to resist yellowing from UV exposure — a real problem up north.</p><p>Plug-and-play wiring harness makes installation a weekend job. Grab a mate, crack a cold one, and get your rig lit up properly. This is the kind of car accessory online Australia tradies and four-wheel drivers don\'t shut up about once they\'ve fitted one.</p><p><strong>Stock moves fast on this one. Lock yours in and we\'ll have it on the way to you this week.</strong></p>', 'LED Light Bar 22 Inch Spot Flood Combo 4WD Driving', '22-inch 120W LED light bar with spot-flood combo beam — IP67 waterproof 4WD driving light built for Aussie off-road conditions. Wiring harness and brackets included.', 'publish', 'open', 'closed', '', 'led-light-bar-22-inch-spot-flood-combo-4wd-driving', '', '', '2026-04-19 21:20:20', '2026-04-19 11:20:20', '', '0', 'https://localhost/auto/product/led-light-bar-22-inch-spot-flood-combo-4wd-driving/', '0', 'product', '', '0'),
('42', '1', '2026-04-19 21:03:41', '2026-04-19 11:03:41', '<h3>Your Rig Deserves Better Than a Service Station Sponge</h3><p>A hard day\'s work deserves a clean rig at the end of it. The LetsDrive 16-piece microfibre detailing kit gives you everything you need to wash, polish and protect your vehicle without scratching the paint or streaking the glass. Aussie-tested on everything from dusty work utes to weekend 4WDs.</p><ul><li><strong>16-piece complete kit</strong> — includes wash mitts, detailing cloths, glass cloths, wheel cloths and applicator pads so you\'ve got the right tool for every surface</li><li><strong>880 GSM ultra-plush microfibre cloths</strong> — thick, heavy-weight fabric lifts grime and polishing compound without leaving scratches or lint behind</li><li><strong>Colour-coded system</strong> — separate cloths for paint, glass, wheels and interior so you\'re not cross-contaminating dirty wheel cleaner onto your duco</li><li><strong>Machine washable and reusable</strong> — throw the lot in a delicates bag, wash cold and they come out ready for the next detail — no single-use waste</li><li><strong>Works on any vehicle</strong> — utes, 4WDs, vans, sports cars — these cloths handle any paint type, clear coat, ceramic coating or uncoated surfaces</li></ul><p>Stop wasting money on disposable wipes and scratchy chamois leathers from the hardware shop. A proper microfibre kit is the foundation of any real car care routine and this set covers you from bumper to bumper.</p><p>Compact storage bag included so everything lives together in the garage or boot. It\'s one of the best value car accessories you can buy online in Australia right now.</p><p><strong>Order before 2PM and we\'ll dispatch same business day. Grab a couple — they make a ripper gift for the car enthusiast in your crew.</strong></p>', 'Microfibre Car Detailing Kit 16-Piece Wash &amp; Polish Set', '16-piece 880GSM microfibre car detailing kit with colour-coded cloths, wash mitts and applicator pads — professional car care for Australian utes and 4WDs at a tradie-friendly price.', 'publish', 'open', 'closed', '', 'microfibre-car-detailing-kit-16-piece-wash-polish-set', '', '', '2026-04-19 21:20:15', '2026-04-19 11:20:15', '', '0', 'https://localhost/auto/product/microfibre-car-detailing-kit-16-piece-wash-polish-set/', '0', 'product', '', '0'),
('43', '1', '2026-04-19 21:03:42', '2026-04-19 11:03:42', '<h3>Gear Up Your Ute — Keep Your Load Covered, Locked and Dry</h3><p>Rain, sun, nosy blokes at the servo — a roll-up tonneau cover sorts all of it in one go. The LetsDrive waterproof tonneau cover is engineered specifically for dual cab utes and snaps on in minutes with no drilling required. Protect your gear, improve your fuel economy and give your rig a cleaner, sharper look on and off the worksite.</p><ul><li><strong>Heavy-duty 600D Oxford canvas with PVC backing</strong> — UV-stabilised and fully waterproof, tested against Queensland downpours and outback sun without fading or cracking</li><li><strong>Tool-free clip-on installation</strong> — aluminium side rails clamp directly onto the tray lip, no drilling into your tub, removable without damage in minutes</li><li><strong>Smooth roll-up design with Velcro straps</strong> — rolls forward cleanly and straps out of the way when you need full tray access, secure and rattle-free at highway speeds</li><li><strong>Lockable tailgate compatibility</strong> — works with your factory tailgate lock to keep the tray fully secured against theft at job sites and campsites</li><li><strong>Available for HiLux, Ranger, BT-50, Navara and Colorado</strong> — model-specific fit ensures a clean flush edge with no gaps or sagging in the middle</li></ul><p>Fuel savings are a genuine bonus here. A fitted tonneau cover reduces aerodynamic drag over the tray which translates to real savings at the bowser — especially noticeable on highway runs. When you\'re doing kilometres every week for work, that adds up.</p><p>This is one of the most popular ute accessories in Australia for a reason. Simple, tough, and it does exactly what it needs to do without any fuss.</p><p><strong>Select your ute model above and get it on the way to you. Fast delivery Australia-wide, order today.</strong></p>', 'Ute Tonneau Cover Roll Up Dual Cab Waterproof Tarp', 'Roll-up waterproof tonneau cover for dual cab utes — tool-free clip-on install, UV-stabilised canvas, fits HiLux, Ranger, Navara and more. A must-have ute accessory in Australia.', 'publish', 'open', 'closed', '', 'ute-tonneau-cover-roll-up-dual-cab-waterproof-tarp', '', '', '2026-04-19 21:20:11', '2026-04-19 11:20:11', '', '0', 'https://localhost/auto/product/ute-tonneau-cover-roll-up-dual-cab-waterproof-tarp/', '0', 'product', '', '0'),
('44', '1', '2026-04-19 21:03:42', '2026-04-19 11:03:42', '<h3>Bogged in the Sand or Mud? Self-Recover in Under Five Minutes</h3><p>There\'s no worse feeling than being axle-deep in soft sand with no one around and the tide coming in — or worse, your missus watching. The LetsDrive recovery tracks are the simplest, most reliable self-recovery tool you can carry. Shove them under the tyres, drive out, done. No winch, no drama, no embarrassment.</p><ul><li><strong>High-tensile nylon polymer construction</strong> — rated to 4,000kg per track, handles the weight of heavily loaded 4WDs, caravans and camper trailers without cracking or deforming</li><li><strong>Aggressive bi-directional tread pattern</strong> — digs into sand, mud, snow and loose gravel for maximum grip and traction from the first wheel rotation</li><li><strong>Tapered nose design</strong> — slides cleanly under a sunken tyre even when you\'re well and truly bogged, no digging required in most situations</li><li><strong>Built-in carry handle and stacking slots</strong> — stack and store them on a roof rack, spare tyre mount or inside a storage bag without taking up valuable boot space</li><li><strong>UV and chemical resistant</strong> — won\'t degrade from fuel spills, tyre rubber, sunscreen or years of outback UV exposure, Aussie-tested and long-lasting</li></ul><p>These aren\'t lightweight camping trinkets. At 1.1kg each, they\'re dense, solid and serious about doing the job in the worst conditions Australia can throw at them — from the Simpson Desert to the Fraser Island beach track.</p><p>Every touring 4WD and off-road rig in Australia should have a set behind the seat or strapped to the rack. Pair them with a snatch strap and shovel and you\'ve got a recovery kit that handles 90% of situations without needing anyone else\'s help.</p><p><strong>Don\'t head off-road without them. Grab a set now — stock of this colour sells out regularly so don\'t sleep on it.</strong></p>', 'Recovery Tracks Sand Mud 4WD Escape Boards Set of 2', 'Set of 2 heavy-duty 4WD recovery tracks rated to 4,000kg — self-recovery from sand, mud and snow for Australian off-road adventurers. Aggressive tread, UV resistant build.', 'publish', 'open', 'closed', '', 'recovery-tracks-sand-mud-4wd-escape-boards-set-of-2', '', '', '2026-04-19 21:20:07', '2026-04-19 11:20:07', '', '0', 'https://localhost/auto/product/recovery-tracks-sand-mud-4wd-escape-boards-set-of-2/', '0', 'product', '', '0'),
