('52', '0', '2026-04-19 22:00:31', '2026-04-19 12:00:31', '@import url(\"https://fonts.googleapis.com/css2?family=Barlow:wght@300;400;600;700;800;900&family=Barlow+Condensed:wght@600;700;800&family=Oswald:wght@400;500;600;700&display=swap\");\n\n/* Global font overrides */\nbody, p, li, td, input, button, select, textarea {\n  font-family: \"Barlow\", sans-serif !important;\n}\nh1, h2, h3, h4, h5, h6,\n.woocommerce-loop-product__title,\n.product_title,\n.woocommerce h1, .woocommerce h2 {\n  font-family: \"Oswald\", sans-serif !important;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n/* Header dark background */\n#masthead, .ast-header-sticked, .site-header {\n  background: #1A1A2E !important;\n}\n.ast-site-identity a, .site-title a { color: #F5A623 !important; }\n.main-header-menu > li > a, .main-navigation a {\n  color: #F5F5F0 !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 600 !important;\n  letter-spacing: 0.5px;\n}\n.main-header-menu > li > a:hover { color: #E8502A !important; }\n\n/* WooCommerce product cards */\n.woocommerce ul.products li.product .button {\n  background: #E8502A !important;\n  color: #fff !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n  font-size: 13px !important;\n}\n.woocommerce ul.products li.product .button:hover {\n  background: #c73f1f !important;\n}\n.woocommerce ul.products li.product {\n  border-radius: 6px;\n  overflow: hidden;\n  box-shadow: 0 4px 16px rgba(26,26,46,0.08);\n  border: 1px solid #e5e7eb;\n  transition: transform 0.25s, box-shadow 0.25s;\n}\n.woocommerce ul.products li.product:hover {\n  transform: translateY(-4px);\n  box-shadow: 0 12px 32px rgba(232,80,42,0.12);\n  border-color: #E8502A;\n}\n/* Price */\n.woocommerce .price, .woocommerce-page .price {\n  color: #E8502A !important;\n  font-weight: 700 !important;\n  font-family: \"Barlow\", sans-serif !important;\n}\n/* Add to cart - single product */\n.woocommerce .single_add_to_cart_button {\n  background: #E8502A !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n  padding: 16px 40px !important;\n}\n.woocommerce .single_add_to_cart_button:hover { background: #c73f1f !important; }\n/* Cart/checkout */\n.woocommerce .checkout-button,\n.woocommerce a.button.alt,\n.woocommerce button.button.alt {\n  background: #E8502A !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n}\n/* Sale badge */\n.woocommerce span.onsale {\n  background: #E8502A !important;\n  border-radius: 4px !important;\n  font-family: \"Barlow\", sans-serif !important;\n  font-weight: 700 !important;\n}\n/* Star ratings */\n.woocommerce .star-rating span::before,\n.woocommerce .star-rating::before { color: #F5A623; }\n/* Breadcrumbs */\n.woocommerce .woocommerce-breadcrumb a { color: #E8502A; }\n/* WooCommerce notices */\n.woocommerce-message { border-top-color: #E8502A !important; }\n/* Footer background */\n.ast-small-footer, footer.ast-small-footer { background: #1A1A2E !important; color: #9ca3af !important; }\n.ast-small-footer a { color: #F5A623 !important; }\n/* Mobile hamburger */\n@media (max-width: 768px) {\n  .ast-mobile-menu-trigger-fill { background: #E8502A !important; }\n  #masthead { border-bottom: 2px solid #E8502A !important; }\n}\n/* ── Homepage: remove container padding, hide page title ── */\n.home .entry-title,\n.home .ast-page-header,\n.home .page-header { display: none !important; }\n\n.home .ast-container,\n.home .entry-content { padding-left: 0 !important; padding-right: 0 !important; max-width: 100% !important; }\n\n.home .site-content .ast-container { padding: 0 !important; }\n.home article.page { padding: 0 !important; margin: 0 !important; }\n.home .entry-content .wp-block-group__inner-container { max-width: 100%; }\n\n/* Fix full-width page on Astra */\n.page-template-page-fullwidth .ast-container,\n.page-template-page-fullwidth .entry-content { max-width: 100% !important; padding: 0 !important; }\n\n/* Remove top/bottom spacing on homepage */\n.home #content.site-content { padding-top: 0 !important; }\n.home .ast-article-single { padding: 0 !important; margin: 0 !important; }\n', 'Custom CSS', '', 'inherit', 'closed', 'closed', '', '36-revision-v1', '', '', '2026-04-19 22:00:31', '2026-04-19 12:00:31', '', '36', 'https://letsdrive.au/?p=52', '0', 'revision', '', '0'),
